// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.Notification.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(notification.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *NotificationUpsertBulk) UpdateNewValues() *NotificationUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(notification.FieldID)
			}
			if _, exists := b.mutation.UserID(); exists {
				s.SetIgnore(notification.FieldUserID)
			}
			if _, exists := b.mutation.GetType(); exists {
				s.SetIgnore(notification.FieldType)
			}
			if _, exists := b.mutation.Category(); exists {
				s.SetIgnore(notification.FieldCategory)
			}
			if _, exists := b.mutation.ContentKind(); exists {
				s.SetIgnore(notification.FieldContentKind)
			}
			if _, exists := b.mutation.TitleKey(); exists {
				s.SetIgnore(notification.FieldTitleKey)
			}
			if _, exists := b.mutation.BodyKey(); exists {
				s.SetIgnore(notification.FieldBodyKey)
			}
			if _, exists := b.mutation.Params(); exists {
				s.SetIgnore(notification.FieldParams)
			}
			if _, exists := b.mutation.CampaignRevisionID(); exists {
				s.SetIgnore(notification.FieldCampaignRevisionID)
			}
			if _, exists := b.mutation.ActionPath(); exists {
				s.SetIgnore(notification.FieldActionPath)
			}
			if _, exists := b.mutation.SourceEventID(); exists {
				s.SetIgnore(notification.FieldSourceEventID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(notification.FieldCreatedAt)
			}
			if _, exists := b.mutation.ExpiresAt(); exists {
				s.SetIgnore(notification.FieldExpiresAt)
			}
		}
	}))
	return u
}

